import UIKit

enum AppImageBase64 {
    static let aovAvatar =
        ""
}

enum AppImageCatalog {
    static let aovAvatar = decode(
        AppImageBase64.aovAvatar
    )

    static func gameAvatar(for bundleIdentifier: String) -> UIImage? {
        switch bundleIdentifier {
        case "com.garena.game.kgvn":
            return aovAvatar
        default:
            return nil
        }
    }

    private static func decode(_ base64: String) -> UIImage? {
        guard
            let data = Data(
                base64Encoded: base64,
                options: .ignoreUnknownCharacters
            )
        else {
            return nil
        }
        return UIImage(data: data)
    }
}
